function demoMain(idx,label){
  var flows=[["auth","profile","orders"],["cart","checkout","receipt"],["upload","process","notify"]];
  var f=flows[idx%flows.length];var ok=true;var steps=[];
  f.forEach(function(svc,i){var latency=20+i*15+(idx*7)%30;steps.push(svc+"@"+latency+"ms");if(latency>90)ok=false;});
  return "["+label+"] integration flow "+f.join("->")+": "+steps.join(", ")+" => "+(ok?"ALL STAGES OK":"STAGE TIMEOUT");
}

